addLab('logistic-contrast','Logistic與對比表示','數值計算','二元logistic機率及指定正負向量的margin式對比損失各自計算。',[LN('x','x',2,calcUnary("-",(5),"-5"),5,.1),LN('w','w',1,calcUnary("-",(3),"-3"),3,.1),LN('b','b',0,calcUnary("-",(5),"-5"),5,.1),LN('positive','正樣本距離',.2,0,3,.1),LN('negative','負樣本距離',.8,0,3,.1),LN('margin','距離margin',1,.1,3,.1)],v=>({metrics:[['logit',calcBinary("+",(calcBinary("*",(v.w),(v.x),"v.w*v.x")),(v.b),"v.w*v.x+v.b")],['sigmoid機率',lsig(calcBinary("+",(calcBinary("*",(v.w),(v.x),"v.w*v.x")),(v.b),"v.w*v.x+v.b"))],['正對平方距離',calcBinary("**",(v.positive),(2),"v.positive**2")],['負對margin懲罰',calcBinary("**",(calcMath("max",[0,calcBinary("-",(v.margin),(v.negative),"v.margin-v.negative")],"Math.max(0,v.margin-v.negative)")),(2),"Math.max(0,v.margin-v.negative)**2")]],lines:['對比損失版本很多；此例使用正對距離平方及負對hinge平方。']}),'邏輯斯回歸|對比損失');
