addLab('serving','請求排程與延遲／吞吐','實際演算法','固定6個同時到達的請求，以同步批次或簡化連續批次排程。每詞元步長固定，無真實硬體。',[LS('mode','排程','batch',['batch:整批等最長完成','continuous:槽位完成即補新請求']),LN('slots','同時槽位',2,1,6),LN('prefill','每請求prefill毫秒',20,0,200),LN('token','每詞元毫秒',10,1,100)],v=>{const lengths=calcValue("lengths",([2,8,3,6,1,5])),rows=calcValue("rows",([]));let finish=calcValue("finish",(0));if(calcBinary("===",(v.mode),('batch'),"v.mode==='batch'")){for(let i=calcValue("i",(0));calcBinary("<",(i),(calcValue("lengths.length",(lengths.length))),"i<lengths.length");calcValue("i+=v.slots",(i=calcBinary("+",i,(v.slots),"i+=v.slots")))){const chunk=calcValue("chunk",(lengths.slice(i,calcBinary("+",(i),(v.slots),"i+v.slots")))),duration=calcValue("duration",(calcBinary("+",(v.prefill),(calcBinary("*",(calcMath("max",[...chunk],"Math.max(...chunk)")),(v.token),"Math.max(...chunk)*v.token")),"v.prefill+Math.max(...chunk)*v.token")));chunk.forEach((n,j)=>rows.push([calcBinary("+",(calcBinary("+",(i),(j),"i+j")),(1),"i+j+1"),n,calcBinary("+",(finish),(v.prefill),"finish+v.prefill"),calcBinary("+",(finish),(duration),"finish+duration")]));calcValue("finish+=duration",(finish=calcBinary("+",finish,(duration),"finish+=duration")))}}else{const slots=calcValue("slots",(Array(v.slots).fill(0)));lengths.forEach((n,i)=>{const k=calcValue("k",(slots.indexOf(calcMath("min",[...slots],"Math.min(...slots)")))),start=calcValue("start",(slots[k]));calcValue("slots[k]+=v.prefill+n*v.token",(slots[k]+=calcBinary("+",(v.prefill),(calcBinary("*",(n),(v.token),"n*v.token")),"v.prefill+n*v.token")));rows.push([calcBinary("+",(i),(1),"i+1"),n,calcBinary("+",(start),(v.prefill),"start+v.prefill"),slots[k]])});calcValue("finish=Math.max(...slots)",(finish=calcMath("max",[...slots],"Math.max(...slots)")))}return {metrics:[['整體完成時間ms',finish],['吞吐請求/秒',calcBinary("/",(6000),(finish),"6000/finish")],['平均首詞元等待近似ms',lmean(rows.map(r=>calcBinary("+",(r[2]),(v.token),"r[2]+v.token")))],['生成詞元總數',lengths.reduce((a,b)=>calcBinary("+",(a),(b),"a+b"),0)]],table:{headers:['請求','輸出詞元數','prefill完成ms','完成ms'],rows},lines:['連續槽位模型忽略GPU共享、padding與prefill干擾，不能作商用引擎效能預測。']}} ,'推論|推論引擎|模型服務|延遲|吞吐量|首詞元時間|詞元間延遲|每秒詞元數|批次推論|動態批次|連續批次');
addLab('cache-speculate','前綴快取與推測成本','數值計算','輸入假設成本與命中／接受率比較理論成本；非真實生成時間。',[LN('prefix','重複前綴詞元',1000,0,10000),LN('requests','請求數',10,1,100),LN('hit','快取命中率',.8,0,1,.05),LN('draft','草稿候選數',4,1,10),LN('accept','草稿接受率',.7,0,1,.05),LN('draftcost','每候選草稿成本',.1,.01,1,.01)],v=>({metrics:[['無快取前綴成本單位',calcBinary("*",(v.prefix),(v.requests),"v.prefix*v.requests")],['假設首次建快取後成本',calcBinary("+",(v.prefix),(calcBinary("*",(calcBinary("*",(calcBinary("-",(v.requests),(1),"v.requests-1")),(v.prefix),"(v.requests-1)*v.prefix")),(calcBinary("-",(1),(v.hit),"1-v.hit")),"(v.requests-1)*v.prefix*(1-v.hit)")),"v.prefix+(v.requests-1)*v.prefix*(1-v.hit)")],['每次驗證期望前進詞元（簡化）',calcBinary("+",(1),(calcBinary("*",(v.draft),(v.accept),"v.draft*v.accept")),"1+v.draft*v.accept")],['每前進詞元驗證＋草稿成本',calcBinary("/",(calcBinary("+",(1),(calcBinary("*",(v.draft),(v.draftcost),"v.draft*v.draftcost")),"1+v.draft*v.draftcost")),(calcBinary("+",(1),(calcBinary("*",(v.draft),(v.accept),"v.draft*v.accept")),"1+v.draft*v.accept")),"(1+v.draft*v.draftcost)/(1+v.draft*v.accept)")]],lines:['接受率視作獨立平均近似；真實推測解碼需遵守目標分布驗證規則。']}),'前綴快取|推測解碼');
addLab('roofline','硬體與記憶體瓶頸','數值計算','用運算量／峰值及搬移量／頻寬算理想下限，取較大者；這不是CPU/GPU/NPU實測。',[LN('flops','工作量（十億FLOPs）',100,1,10000),LN('compute','硬體算力（TFLOP/s）',10,.1,1000,.1),LN('data','需搬移資料（GB）',8,.1,1000,.1),LN('bandwidth','頻寬（GB/s）',100,1,3000),LN('overhead','固定開銷ms',1,0,100)],v=>{const compute=calcValue("compute",(calcBinary("/",(v.flops),(calcBinary("*",(v.compute),(1000),"v.compute*1000")),"v.flops/(v.compute*1000)"))),memory=calcValue("memory",(calcBinary("/",(v.data),(v.bandwidth),"v.data/v.bandwidth")));return {metrics:[['計算下限ms',calcBinary("*",(compute),(1000),"compute*1000")],['搬移下限ms',calcBinary("*",(memory),(1000),"memory*1000")],['簡化總下限ms',calcBinary("+",(calcBinary("*",(calcMath("max",[compute,memory],"Math.max(compute,memory)")),(1000),"Math.max(compute,memory)*1000")),(v.overhead),"Math.max(compute,memory)*1000+v.overhead")],['主要下限',calcBinary(">",(memory),(compute),"memory>compute")?'頻寬':'計算']],lines:['硬體可支援算子、精度、利用率與裝置熱限制，都會讓實際結果偏離理論下限。']}} ,'邊緣 AI|裝置端 AI|中央處理器|圖形處理器|神經處理單元|張量處理器|記憶體頻寬|浮點運算量');
addLab('parallel-checkpoint','平行、重計算與卸載','數值計算','以指定總記憶體與階段數估算單卡分攤／管線利用；純比較模型，忽略大部分通訊細節。',[LN('model','模型相關記憶體GiB',16,1,200),LN('activation','激活GiB',8,1,100),LN('devices','裝置數',4,1,16),LN('micro','微批次數',8,1,64),LS('mode','分配','data',['data:資料平行（完整權重）','tensor:張量平行（理想均分）','pipeline:管線平行（理想均分）']),LB('checkpoint','重計算：激活減半'),LB('offload','卸載：模型相關狀態減半')],v=>{const m=calcValue("m",(calcBinary("*",(v.model),(v.offload?.5:1),"v.model*(v.offload?.5:1)"))),a=calcValue("a",(calcBinary("*",(v.activation),(v.checkpoint?.5:1),"v.activation*(v.checkpoint?.5:1)")));return {metrics:[['單卡簡化GiB',calcBinary("+",(calcBinary("===",(v.mode),('data'),"v.mode==='data'")?m:calcBinary("/",(m),(v.devices),"m/v.devices")),(a),"(v.mode==='data'?m:m/v.devices)+a")],['理想管線利用率',calcBinary("/",(v.micro),(calcBinary("-",(calcBinary("+",(v.micro),(v.devices),"v.micro+v.devices")),(1),"v.micro+v.devices-1")),"v.micro/(v.micro+v.devices-1)")]],lines:['重計算與卸載減半是假設，不是保證。資料平行不會自動均分完整模型權重。','記錄速度、通訊與還原正確性，才能評估實際取捨。']}} ,'資料平行|模型平行|張量平行|管線平行|分散式訓練|梯度檢查點|激活值重計算|記憶體卸載');
addLab('fairness','群體公平與混淆矩陣','數值計算','比較兩群相同陽性總數的Recall及假陽性率；不能單靠兩項指標認定全面公平。',[LN('tpA','A群TP',8,0,10),LN('fpA','A群FP',2,0,90),LN('tpB','B群TP',5,0,10),LN('fpB','B群FP',5,0,90)],v=>({table:{headers:['群體','Recall（各10陽性）','FPR（各90陰性）'],rows:[['A',calcBinary("/",(v.tpA),(10),"v.tpA/10"),calcBinary("/",(v.fpA),(90),"v.fpA/90")],['B',calcBinary("/",(v.tpB),(10),"v.tpB/10"),calcBinary("/",(v.fpB),(90),"v.fpB/90")]]},metrics:[['Recall差距',calcBinary("/",(calcMath("abs",[calcBinary("-",(v.tpA),(v.tpB),"v.tpA-v.tpB")],"Math.abs(v.tpA-v.tpB)")),(10),"Math.abs(v.tpA-v.tpB)/10")]],lines:['此處固定群體規模，真實分析還需資料代表性、不確定性及情境錯誤成本。']}),'公平性');
addLab('privacy','差分隱私噪聲與個資遮罩','實際演算法','以敏感度1的計數加Laplace噪聲；此例單次查詢，未實作完整隱私預算管理。',[LN('count','原始計數',100,0,1000),LN('epsilon','ε',1,.1,10,.1),LN('seed','噪聲種子（僅演示）',42,1,10000),LT('text','虛構文字','測試信箱 demo@example.com，電話 0912-345-678。')],v=>{const u=calcValue("u",(calcBinary("-",(lrandom(v.seed)()),(.5),"lrandom(v.seed)()-.5"))),noise=calcValue("noise",(calcBinary("/",(calcBinary("*",(calcUnary("-",(calcMath("sign",[u],"Math.sign(u)")),"-Math.sign(u)")),(calcMath("log",[calcBinary("-",(1),(calcBinary("*",(2),(calcMath("abs",[u],"Math.abs(u)")),"2*Math.abs(u)")),"1-2*Math.abs(u)")],"Math.log(1-2*Math.abs(u))")),"-Math.sign(u)*Math.log(1-2*Math.abs(u))")),(v.epsilon),"-Math.sign(u)*Math.log(1-2*Math.abs(u))/v.epsilon")));return {metrics:[['Laplace噪聲',noise],['發布計數（未裁切）',calcBinary("+",(v.count),(noise),"v.count+noise")]],lines:[`模式遮罩：${v.text.replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]+/g,'[EMAIL]').replace(/09\d{2}[- ]?\d{3}[- ]?\d{3}/g,'[PHONE]')}`,'固定種子僅供重現教學，不能作真實差分隱私保護。正規式也不能偵測所有PII。']}} ,'個人可識別資訊|差分隱私|成員推斷攻擊|模型反演');
addLab('guardrails','提示注入與最小權限','流程模擬','在本地假任務中，選擇外部內容是否被當成指令，以及寫入／連外權限；不執行真實攻擊。',[LB('untrusted','外部文件含惡意指令',true),LB('isolate','把文件隔離為不可信資料',true),LB('network','允許外傳資料'),LB('write','允許寫入'),LB('review','敏感操作要求人工確認',true)],v=>{const injected=calcValue("injected",(v.untrusted&&calcUnary("!",(v.isolate),"!v.isolate"))),exposed=calcValue("exposed",(injected&&v.network&&calcUnary("!",(v.review),"!v.review")));return {steps:['讀取外部文件',v.isolate?'僅作資料處理':'錯把內容當指令',v.network?'可連外':'連外被限制',v.write?'可寫入':'寫入被限制',v.review?'待人工核對後才可行動':'無人工關卡'],metrics:[['此情境外傳風險',exposed?'暴露':'被本例條件攔阻'],['此情境寫入風險',injected&&v.write&&calcUnary("!",(v.review),"!v.review")?'暴露':'被本例條件攔阻']],lines:['這是明確規則的防禦流程，不證明真實系統已免疫所有注入或越獄。','沙箱與最小權限須由執行環境強制，不是只寫在提示詞。']}} ,'沙箱|AI 安全|AI 資安|提示注入|間接提示注入|越獄|最小權限原則|安全防護機制|人工監督|內容審核');
addLab('adversarial','線性模型擾動與投毒','數值計算','固定線性分類器z=x₁+x₂−1，檢查指定擾動是否跨界；另對訓練標籤做可見翻轉，未攻擊外部模型。',[LN('x','x₁',.6,calcUnary("-",(2),"-2"),2,.05),LN('y','x₂',.6,calcUnary("-",(2),"-2"),2,.05),LN('delta','兩軸共同擾動',calcUnary("-",(.15),"-.15"),calcUnary("-",(1),"-1"),1,.05),LN('poison','假資料標籤翻轉筆數',0,0,10),LB('trigger','加入後門觸發條件')],v=>{const z=calcValue("z",(calcBinary("-",(calcBinary("+",(v.x),(v.y),"v.x+v.y")),(1),"v.x+v.y-1"))),z2=calcValue("z2",(calcBinary("-",(calcBinary("+",(calcBinary("+",(v.x),(v.y),"v.x+v.y")),(calcBinary("*",(2),(v.delta),"2*v.delta")),"v.x+v.y+2*v.delta")),(1),"v.x+v.y+2*v.delta-1")));return {metrics:[['原分數',z],['擾動分數',z2],['原類別',calcBinary(">=",(z),(0),"z>=0")?1:0],['擾動類別',v.trigger?1:calcBinary(">=",(z2),(0),"z2>=0")?1:0],['可見污染比例',calcBinary("/",(v.poison),(10),"v.poison/10")]],lines:['後門開關是明示規則，不是秘密植入模型；資料投毒與模型投毒發生位置不同。','觀察決策邊界與穩健性，而非測試未經授權系統。']}} ,'穩健性|對抗樣本|對抗攻擊|資料投毒|模型投毒|後門攻擊|模型竊取|紅隊測試');
